const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;
const BACKSLASH = 0x5c;

export function formatPythonBytesLiteral(bytes) {
  const quoteByte = shouldUseDoubleQuote(bytes) ? DOUBLE_QUOTE : SINGLE_QUOTE;
  const quote = String.fromCharCode(quoteByte);
  let body = '';

  for (const byte of bytes) {
    if (byte === quoteByte) {
      body += `\\${quote}`;
      continue;
    }

    if (byte === BACKSLASH) {
      body += '\\\\';
      continue;
    }

    if (byte === 0x09) {
      body += '\\t';
      continue;
    }

    if (byte === 0x0a) {
      body += '\\n';
      continue;
    }

    if (byte === 0x0d) {
      body += '\\r';
      continue;
    }

    if (byte >= 0x20 && byte <= 0x7e) {
      body += String.fromCharCode(byte);
      continue;
    }

    body += `\\x${byte.toString(16).padStart(2, '0')}`;
  }

  return `b${quote}${body}${quote}`;
}

function shouldUseDoubleQuote(bytes) {
  let hasSingleQuote = false;
  let hasDoubleQuote = false;

  for (const byte of bytes) {
    if (byte === SINGLE_QUOTE) {
      hasSingleQuote = true;
    }

    if (byte === DOUBLE_QUOTE) {
      hasDoubleQuote = true;
    }
  }

  return hasSingleQuote && !hasDoubleQuote;
}

