import {
  CliParseError,
  formatArgparseFailure,
  parseTest3Args,
} from '../cli/parseTest3Args.mjs';
import {
  buildTwoFieldStruct,
  ConstructBuildError,
  formatConstructBuildFailure,
} from '../construct/buildTwoFieldStruct.mjs';
import { formatPythonBytesLiteral } from '../format/pythonBytesLiteral.mjs';
import { basename } from '../runtime/pathUtils.mjs';

export function runTest3(argv, io = { stdout: process.stdout, stderr: process.stderr }) {
  const programName = basename(argv[1]) || 'test3.mjs';

  try {
    const parseResult = parseTest3Args(argv.slice(2), programName);

    if (parseResult.kind === 'help') {
      io.stdout.write(parseResult.text);
      return 0;
    }

    const data = buildTwoFieldStruct({
      field1: parseResult.values.a,
      field2: parseResult.values.b,
    });

    io.stdout.write(`${formatPythonBytesLiteral(data)}\n`);
    return 0;
  } catch (error) {
    if (error instanceof CliParseError) {
      io.stderr.write(formatArgparseFailure(programName, error.message));
      return 2;
    }

    if (error instanceof ConstructBuildError) {
      io.stderr.write(formatConstructBuildFailure(error));
      return 1;
    }

    throw error;
  }
}

