const NEGATIVE_NUMBER_TOKEN = /^-\d+$|^-\d*\.\d+$/;
const PYTHON_INT_TOKEN = /^[+-]?(?:\d(?:_?\d)*)$/;

export class CliParseError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CliParseError';
  }
}

export function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B\n`;
}

export function formatHelpText(programName) {
  return (
    `${formatUsage(programName)}\n` +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n'
  );
}

export function formatArgparseFailure(programName, message) {
  return `${formatUsage(programName)}${programName}: error: ${message}\n`;
}

export function parseTest3Args(argv, programName) {
  let a;
  let b;
  let parsingOptions = true;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (parsingOptions && (token === '-h' || token === '--help')) {
      return {
        kind: 'help',
        text: formatHelpText(programName),
      };
    }

    if (parsingOptions && token === '--') {
      parsingOptions = false;
      continue;
    }

    if (parsingOptions && token.startsWith('--a=')) {
      a = parsePythonIntOption('--a', token.slice('--a='.length));
      continue;
    }

    if (parsingOptions && token.startsWith('--b=')) {
      b = parsePythonIntOption('--b', token.slice('--b='.length));
      continue;
    }

    if (parsingOptions && (token === '--a' || token === '--b')) {
      const nextToken = argv[index + 1];

      if (nextToken === undefined || nextToken === '--' || looksLikeAnotherOption(nextToken)) {
        throw new CliParseError(`argument ${token}: expected one argument`);
      }

      const parsedValue = parsePythonIntOption(token, nextToken);
      if (token === '--a') {
        a = parsedValue;
      } else {
        b = parsedValue;
      }

      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missing = [];
  if (a === undefined) {
    missing.push('--a');
  }
  if (b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    throw new CliParseError(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    throw new CliParseError(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    kind: 'ok',
    values: { a, b },
  };
}

function looksLikeAnotherOption(token) {
  if (!token.startsWith('-') || token === '-') {
    return false;
  }

  return !NEGATIVE_NUMBER_TOKEN.test(token);
}

function parsePythonIntOption(optionName, rawValue) {
  if (!PYTHON_INT_TOKEN.test(rawValue)) {
    throw new CliParseError(`argument ${optionName}: invalid int value: ${quoteForError(rawValue)}`);
  }

  return BigInt(rawValue.replaceAll('_', ''));
}

function quoteForError(value) {
  return `'${String(value).replaceAll('\\', '\\\\').replaceAll('\'', '\\\'')}'`;
}

